import{_ as e,o as a,c as d,a0 as r}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"基础教程","description":"","frontmatter":{},"headers":[],"relativePath":"basic/index.md","filePath":"basic/index.md","lastUpdated":1793354072000}'),o={name:"basic/index.md"};function i(h,t,c,s,n,l){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="基础教程" tabindex="-1">基础教程 <a class="header-anchor" href="#基础教程" aria-label="Permalink to &quot;基础教程&quot;">​</a></h1><p>ZViewer 是多人同步观影、追番与远程共享平台。日常安装与使用看这一章即可；实现细节见<a href="/advanced/">拓展教程</a>。</p><h2 id="快速上手" tabindex="-1">快速上手 <a class="header-anchor" href="#快速上手" aria-label="Permalink to &quot;快速上手&quot;">​</a></h2><h3 id="_1-下载" tabindex="-1">1. 下载 <a class="header-anchor" href="#_1-下载" aria-label="Permalink to &quot;1. 下载&quot;">​</a></h3><p>从 <a href="https://github.com/Zero-wyc/ZViewer/releases" target="_blank" rel="noreferrer">Releases</a> 下载对应系统的压缩包，解压：</p><table tabindex="0"><thead><tr><th>平台</th><th>文件</th></tr></thead><tbody><tr><td>Windows 桌面版</td><td><code>zviewer-windows-x64-GUI.zip</code>（双击 <code>ZViewerDesktop.exe</code>）</td></tr><tr><td>Windows 单文件版</td><td><code>zviewer-windows-x64.zip</code></td></tr><tr><td>Linux</td><td><code>zviewer-linux-x64.tar.gz</code></td></tr></tbody></table><h3 id="_2-启动" tabindex="-1">2. 启动 <a class="header-anchor" href="#_2-启动" aria-label="Permalink to &quot;2. 启动&quot;">​</a></h3><ul><li><strong>Windows 桌面版</strong>：双击 <code>ZViewerDesktop.exe</code>，在窗口里启动 / 停止服务</li><li><strong>Windows 单文件版</strong>：双击 <code>start.bat</code>，进入交互菜单</li><li><strong>Linux</strong>：执行 <code>./start.sh</code>，进入交互菜单</li></ul><p>菜单中选 <code>1</code> 启动服务，访问 <code>http://localhost:3333</code>。各项含义见<a href="/basic/install#交互菜单">安装与部署</a>。</p><h3 id="_3-登录" tabindex="-1">3. 登录 <a class="header-anchor" href="#_3-登录" aria-label="Permalink to &quot;3. 登录&quot;">​</a></h3><p>首次启动自动创建超级管理员 <code>root</code> / <code>root</code>，登录后请立即改密：右上角用户菜单 → 个人资料 → 编辑信息 → 修改密码。</p><h3 id="_4-创建房间" tabindex="-1">4. 创建房间 <a class="header-anchor" href="#_4-创建房间" aria-label="Permalink to &quot;4. 创建房间&quot;">​</a></h3><p>「开始共享」→ 选择模式（一起看 / 投屏）→ 进入房间。把房间号或分享链接发给他人，对方可通过房间号、房间列表或链接加入。</p><h3 id="_5-添加影片" tabindex="-1">5. 添加影片 <a class="header-anchor" href="#_5-添加影片" aria-label="Permalink to &quot;5. 添加影片&quot;">​</a></h3><p>「添加影片」面板选择来源：B站（BV 号或链接解析）、直链（MP4 等）、WebDAV / FTP / OpenList 挂载（需先在个人资料页或后台配置）。点击影片即开始播放，进度实时同步给所有成员。</p><h2 id="端口" tabindex="-1">端口 <a class="header-anchor" href="#端口" aria-label="Permalink to &quot;端口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>端口</th><th>用途</th><th>对外</th></tr></thead><tbody><tr><td>3333/tcp</td><td>统一入口：API、WebSocket、前端页面、<code>/live</code> FLV 代理、<code>/rtc</code> 语音信令</td><td>是</td></tr><tr><td>3333/udp</td><td>语音媒体</td><td>是</td></tr><tr><td>3334</td><td>RTMP 推流（OBS）</td><td>推流时需要</td></tr><tr><td>3337/tcp</td><td>语音 ICE/TCP</td><td>是</td></tr><tr><td>3338/tcp</td><td>语音 TURN/TLS 中继（可选）</td><td>配证书时</td></tr><tr><td>3335</td><td>HTTP-FLV 拉流（内部）</td><td>否</td></tr><tr><td>3336</td><td>LiveKit 信令（内部）</td><td>否</td></tr></tbody></table><h2 id="浏览器要求" tabindex="-1">浏览器要求 <a class="header-anchor" href="#浏览器要求" aria-label="Permalink to &quot;浏览器要求&quot;">​</a></h2><p>需 Chromium 内核 130+（Chrome / Edge 等）。Safari 与 Firefox 对 MSE / MKV 解码支持不完整，可能出现卡顿、无法解码或字幕异常。</p><h2 id="本分区目录" tabindex="-1">本分区目录 <a class="header-anchor" href="#本分区目录" aria-label="Permalink to &quot;本分区目录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>内容</th></tr></thead><tbody><tr><td><a href="/basic/install">安装与部署</a></td><td>单文件 / 源码 / Docker / 数据持久化</td></tr><tr><td><a href="/basic/features">功能说明</a></td><td>全部功能的使用说明</td></tr><tr><td><a href="/basic/mobile">手机端 App</a></td><td>Android / HarmonyOS 客户端与平台差异</td></tr><tr><td><a href="/basic/cli">ZViewer CLI</a></td><td>本地代理客户端安装与使用</td></tr><tr><td><a href="/basic/admin">管理后台</a></td><td>用户审核、房间管理、系统设置</td></tr><tr><td><a href="/basic/network">网络连接与内网穿透</a></td><td>FRP / ZeroTier / IPv6</td></tr><tr><td><a href="/basic/faq">常见问题</a></td><td>证书、WebSocket、数据库等</td></tr></tbody></table><p>需要 HTTPS 时用一键脚本签发并启动：<code>start.bat https</code> / <code>./start.sh https</code>，机制见 <a href="/advanced/https">HTTPS 证书</a>。新手用内网穿透自带的自动 HTTPS，或用自签证书即可——自签只会弹一次警告，不影响使用。</p>',22)])])}const f=e(o,[["render",i]]);export{p as __pageData,f as default};
